def evaluate(s):
    tokens = [ch for ch in s if not ch.isspace()]
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def take():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def expr():
        value = term()
        while peek() in ("+", "-"):
            if take() == "+":
                value = value + term()
            else:
                value = value - term()
        return value

    def term():
        value = factor()
        while peek() in ("*", "/"):
            if take() == "*":
                value = value * factor()
            else:
                value = value / factor()
        return value

    def factor():
        if peek() == "(":
            take()
            value = expr()
            if peek() != ")":
                raise ValueError("expected )")
            take()
            return value
        digits = []
        while peek() is not None and peek().isdigit():
            digits.append(take())
        if not digits:
            raise ValueError("expected number")
        return int("".join(digits))

    result = expr()
    if pos != len(tokens):
        raise ValueError("trailing input")
    return result
